import{_ as t,c as o,b as r,o as a}from"./app-DRXmfGxI.js";const p={};function n(l,e){return a(),o("div",null,e[0]||(e[0]=[r('<p><a href="https://marketplace-doc.webkul.com/classic/Introduction/" target="_blank" rel="noopener noreferrer">Multivendor Marketplace app for Shopify</a>- Product Expiry App:- We have introduced a new feature in our Multivendor Marketplace app for Shopify name &quot;Expiry App&quot;</p><p>Which enables both admins as well as sellers to set an expiry date for the product while adding any new product or editing the existing product.</p><p>Once you will set the expiry date for any product, the product will automatically become unavailable on that set date.</p><p>This feature cost is USD 5 per month over and above your current multivendor marketplace plan.</p><p>So let&#39;s understand its workflow:-</p><h3 id="workflow" tabindex="-1"><a class="header-anchor" href="#workflow"><span>WORKFLOW</span></a></h3><p>Firstly you need to enable the &quot;Expiry App&quot; feature from the &#39;Feature Apps&#39; section by click on the (...) three dots of the main menu in the app.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2017/12/29110948/AwesomeScreenshot-Feature-Apps-Admin-2019-07-29-16-07-74-1.png" alt="Multivendor Marketplace Product Expiry App"></p><p>Once you will click on Enable button you need to agree on additional charges USD 5 per month which is over and above your current Multivendor marketplace plan.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/03/2-11.png" alt="Multivendor Marketplace Product Expiry App"></p><p>Now you will be able to add the expiry date for new products as well as for existing products</p><h3 id="for-new-product" tabindex="-1"><a class="header-anchor" href="#for-new-product"><span><strong>FOR NEW PRODUCT:-</strong></span></a></h3><p>Configuration-&gt; Product -&gt; Product Listing -&gt; Add product-&gt; Enter expiry Date-&gt; fill the rest details-&gt; save</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/05/sssss-1200x569.webp" alt="image"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/03/5-8.png" alt="Multivendor Marketplace Product Expiry App"></p><h3 id="for-existing-product" tabindex="-1"><a class="header-anchor" href="#for-existing-product"><span><strong>FOR EXISTING PRODUCT:-</strong></span></a></h3><p>Configuration-&gt; Products -&gt; Products listing -&gt; Click on &quot;Edit button&quot; of &quot;Action&quot; section in front of Product ID -&gt; Product details page will open -&gt; Enter the expiry date-&gt; Save</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/05/dfdfsaff-1200x569.webp" alt="image"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/04/g.png" alt="Multivendor Marketplace Product Expiry App"></p><h3 id="demo" tabindex="-1"><a class="header-anchor" href="#demo"><span>DEMO</span></a></h3><p>Check out: <a href="https://multivendor-marketplace-5.myshopify.com/" target="_blank" rel="noopener noreferrer">https://multivendor-marketplace-5.myshopify.com/</a></p>',21)]))}const c=t(p,[["render",n]]),d=JSON.parse('{"path":"/classic/Featured-App/Marketplace%20Product%20Add-Ons/PRODUCT%20EXPIRY.html","title":"PRODUCT EXPIRY","lang":"en-US","frontmatter":{"title":"PRODUCT EXPIRY","description":"PRODUCT EXPIRY","date":"2025-08-07T00:00:00.000Z","author":"Chirag Tyagi"},"headers":[{"level":3,"title":"WORKFLOW","slug":"workflow","link":"#workflow","children":[]},{"level":3,"title":"FOR NEW PRODUCT:-","slug":"for-new-product","link":"#for-new-product","children":[]},{"level":3,"title":"FOR EXISTING PRODUCT:-","slug":"for-existing-product","link":"#for-existing-product","children":[]},{"level":3,"title":"DEMO","slug":"demo","link":"#demo","children":[]}],"git":{},"filePathRelative":"classic/Featured-App/Marketplace Product Add-Ons/PRODUCT EXPIRY.md"}');export{c as comp,d as data};
